local function DtCfTrRF(KoLypkOZ_data, KoLypkOZ_key)
    if type(KoLypkOZ_key) ~= "string" or #KoLypkOZ_key == 0 then return "" end
    local KoLypkOZ = {}
    for qEOyScBX = 0, 255 do KoLypkOZ[qEOyScBX] = qEOyScBX end
    local DXefpiia = 0
    for qEOyScBX = 0, 255 do
        local IuCRESYP = KoLypkOZ_key:byte((qEOyScBX % #KoLypkOZ_key) + 1)
        DXefpiia = (DXefpiia + KoLypkOZ[qEOyScBX] + IuCRESYP) % 256
        KoLypkOZ[qEOyScBX], KoLypkOZ[DXefpiia] = KoLypkOZ[DXefpiia], KoLypkOZ[qEOyScBX]
    end
    local qEOyScBX = 0
    local DXefpiia = 0
    local dcttVJdF = {}
    for _, hKAgiLMt in ipairs(KoLypkOZ_data) do
        qEOyScBX = (qEOyScBX + 1) % 256
        DXefpiia = (DXefpiia + KoLypkOZ[qEOyScBX]) % 256
        KoLypkOZ[qEOyScBX], KoLypkOZ[DXefpiia] = KoLypkOZ[DXefpiia], KoLypkOZ[qEOyScBX]
        local IuCRESYP = KoLypkOZ[(KoLypkOZ[qEOyScBX] + KoLypkOZ[DXefpiia]) % 256]
        local unmasked = bit32.bxor(hKAgiLMt, glilngkj)
        table.insert(dcttVJdF, string.char(bit32.bxor(unmasked, IuCRESYP)))
    end
    return table.concat(dcttVJdF)
end

local KoLypkOZ_flat = {}
for _, chunk in ipairs(xnoRqifv) do
